CREATE OR REPLACE FUNCTION public.set_learning_profile_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('request.jwt.claim.role',true)='authenticated' THEN NEW.profile_role:=public.current_profile_role(); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.save_course_content(_course uuid,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.courses; r public.profile_role; institution uuid; scope uuid; result uuid; module jsonb; lesson jsonb; m uuid; questions jsonb; pos integer:=0; BEGIN r:=public.current_profile_role(); IF auth.uid() IS NULL OR r NOT IN ('professor','ies') THEN RAISE EXCEPTION 'Somente autores autorizados'; END IF; scope:=NULLIF(_payload->>'scope_id','')::uuid; IF r='ies' THEN SELECT institution_id INTO institution FROM public.profiles WHERE id=auth.uid(); IF NOT public.organization_permission(institution,'ies','conteudo',scope) THEN RAISE EXCEPTION 'Conteúdo fora do seu escopo'; END IF; END IF; IF length(trim(COALESCE(_payload->>'title','')))<3 THEN RAISE EXCEPTION 'Informe o título'; END IF;
IF _course IS NULL THEN INSERT INTO public.courses(title,slug,description,instructor_id,instructor_name,institution_id,scope_id,published,status) SELECT _payload->>'title',lower(substr(md5(gen_random_uuid()::text),1,16)),COALESCE(_payload->>'description',''),auth.uid(),full_name,institution,scope,false,'rascunho' FROM public.profiles WHERE id=auth.uid() RETURNING id INTO result;
ELSE SELECT * INTO c FROM public.courses WHERE id=_course FOR UPDATE; IF NOT FOUND OR NOT ((r='professor' AND c.instructor_id=auth.uid() AND c.institution_id IS NULL) OR (r='ies' AND public.organization_permission(c.institution_id,'ies','conteudo',c.scope_id))) THEN RAISE EXCEPTION 'Conteúdo não autorizado'; END IF; IF c.published THEN RAISE EXCEPTION 'Suspenda o conteúdo antes de editar'; END IF; UPDATE public.courses SET title=_payload->>'title',description=COALESCE(_payload->>'description',''),status='rascunho',media_approved=false WHERE id=c.id; result:=c.id; END IF;
FOR module IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'modules','[]')) LOOP pos:=pos+1; IF module->>'id' IS NOT NULL THEN SELECT id INTO m FROM public.course_modules WHERE id=(module->>'id')::uuid AND course_id=result; IF m IS NULL THEN RAISE EXCEPTION 'Módulo não autorizado'; END IF; UPDATE public.course_modules SET title=module->>'title',hours=COALESCE((module->>'hours')::numeric,1),game=COALESCE(module->'game','[]') WHERE id=m; ELSE INSERT INTO public.course_modules(course_id,title,position,hours,game) VALUES(result,COALESCE(module->>'title','Módulo '||pos),pos,COALESCE((module->>'hours')::numeric,1),COALESCE(module->'game','[]')) RETURNING id INTO m; END IF;
FOR lesson IN SELECT value FROM jsonb_array_elements(COALESCE(module->'lessons','[]')) LOOP IF lesson->>'id' IS NULL THEN INSERT INTO public.lessons(course_id,module_id,title,duration_min,position,video_path) VALUES(result,m,lesson->>'title',(lesson->>'duration_min')::integer,(lesson->>'position')::integer,lesson->>'video_path'); ELSE UPDATE public.lessons SET title=lesson->>'title',duration_min=(lesson->>'duration_min')::integer,video_path=lesson->>'video_path' WHERE id=(lesson->>'id')::uuid AND module_id=m; END IF; END LOOP;
questions:=module->'questions'; IF questions IS NOT NULL AND jsonb_array_length(questions)>0 THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(questions) q WHERE q->>'question' IS NULL OR jsonb_array_length(q->'options')<2 OR (q->>'answer')::integer<0 OR (q->>'answer')::integer>=jsonb_array_length(q->'options')) THEN RAISE EXCEPTION 'Questões inválidas'; END IF; INSERT INTO public.module_assessments(module_id,questions,minimum_score) VALUES(m,questions,COALESCE((module->>'minimum_score')::numeric,70)) ON CONFLICT(module_id) DO UPDATE SET questions=EXCLUDED.questions,minimum_score=EXCLUDED.minimum_score; END IF; END LOOP;
UPDATE public.courses SET hours=COALESCE((SELECT sum(hours) FROM public.course_modules WHERE course_id=result),1) WHERE id=result; INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),institution,CASE WHEN institution IS NOT NULL THEN 'ies' END,scope,'conteudo_salvo','courses',jsonb_build_object('course_id',result)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.course_action(_course uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.courses; author boolean; BEGIN SELECT * INTO c FROM public.courses WHERE id=_course FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Conteúdo indisponível'; END IF; author:=(public.current_profile_role()='professor' AND c.instructor_id=auth.uid() AND c.institution_id IS NULL) OR public.organization_permission(c.institution_id,'ies','conteudo',c.scope_id);
IF _action='approve' THEN IF NOT public.is_admin() OR public.current_profile_role() IN ('professor','ies','empresa','colaborador') THEN RAISE EXCEPTION 'Revisão administrativa necessária'; END IF; UPDATE public.courses SET media_approved=true,status='publicado',published=true WHERE id=_course;
ELSIF _action='submit' THEN IF NOT author THEN RAISE EXCEPTION 'Acesso negado'; END IF; UPDATE public.courses SET status='em_avaliacao',published=false WHERE id=_course;
ELSIF _action='suspend' THEN IF NOT author AND NOT public.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF; UPDATE public.courses SET status='suspenso',published=false WHERE id=_course;
ELSE RAISE EXCEPTION 'Ação inválida'; END IF; INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),c.institution_id,CASE WHEN c.institution_id IS NOT NULL THEN 'ies' END,c.scope_id,'conteudo_'||_action,'courses',jsonb_build_object('course_id',_course)); END $$;
CREATE OR REPLACE FUNCTION public.author_assessment(_module uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.courses; BEGIN SELECT courses.* INTO c FROM public.courses JOIN public.course_modules m ON m.course_id=courses.id WHERE m.id=_module; IF NOT FOUND OR NOT ((public.current_profile_role()='professor' AND c.instructor_id=auth.uid() AND c.institution_id IS NULL) OR public.organization_permission(c.institution_id,'ies','conteudo',c.scope_id) OR public.is_admin()) THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN (SELECT questions FROM public.module_assessments WHERE module_id=_module); END $$;
REVOKE ALL ON FUNCTION public.save_course_content(uuid,jsonb),public.course_action(uuid,text),public.author_assessment(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_course_content(uuid,jsonb),public.course_action(uuid,text),public.author_assessment(uuid) TO authenticated;